local function C_6()
	local script = LMG2L["LocalScript_6"]

	local button = script.Parent
	local textBox = button.Parent

	button.MouseButton1Click:Connect(function()

		local code = tostring(textBox.Text)

		if code and code ~= "" then

			if not loadstring then
				print("loadstring not supported")
				return
			end

			local compiled, err = loadstring(code)

			if compiled then
				print("Executing...")
				compiled()
			else
				warn("Compile Error:", err)
			end
		else
			warn("Textbox kosong")
		end

	end)
end
